    lessonSummary: "今天学了概率的两种理解方式。理论概率基于数学计算：P=有利结果数/总结果数，前提是每个结果等可能。实验概率基于实际试验：发生次数除以总次数。它们不一定相等——掷硬币10次可能出现7次正面，实验概率0.7不等于理论概率0.5。但大数定律告诉我们：实验次数越多，实验概率越接近理论概率。样本空间是所有可能结果的集合，写清楚它再数有利结果，这个步骤不要省。期望值是长期平均值，掷骰子的期望值是3.5——你永远掷不出3.5，但掷很多次后平均值会趋近它。",
